<?php

$emails = ['demo.supplier@reg.test.invalid', 'registration.acceptance@reg.test.invalid', 'team.acceptance@reg.test.invalid']; $user_storage = \Drupal::entityTypeManager()->getStorage('user'); $node_storage = \Drupal::entityTypeManager()->getStorage('node'); $database = \Drupal::database(); $uids = []; $organization_ids = [];
foreach ($emails as $email) foreach ($user_storage->loadByProperties(['mail' => $email]) as $user) $uids[] = (int) $user->id();
if ($uids) { $org_ids = $node_storage->getQuery()->accessCheck(FALSE)->condition('type', 'reg_supplier_profile')->condition('field_reg_test_record', 1)->condition('uid', $uids, 'IN')->execute(); foreach ($node_storage->loadMultiple($org_ids) as $org) { $organization_ids[] = (int) $org->id(); $related = $node_storage->getQuery()->accessCheck(FALSE)->condition('type', ['reg_supplier_membership', 'reg_bid'], 'IN')->condition('field_reg_supplier_org.target_id', $org->id())->execute(); $node_storage->delete($node_storage->loadMultiple($related)); $org->delete(); } $database->delete('reg_core_supplier_verification')->condition('uid', $uids, 'IN')->execute(); $database->delete('reg_core_supplier_audit')->condition('uid', $uids, 'IN')->execute(); foreach ($emails as $email) $database->delete('reg_core_supplier_invitation')->condition('email', $email)->execute(); $user_storage->delete($user_storage->loadMultiple($uids)); }
if ($organization_ids) $database->delete('reg_core_supplier_audit')->condition('organization_nid', $organization_ids, 'IN')->execute();
$file_storage = \Drupal::entityTypeManager()->getStorage('file'); $file_ids = $file_storage->getQuery()->accessCheck(FALSE)->condition('uri', 'private://supplier-acceptance/%', 'LIKE')->execute(); $file_storage->delete($file_storage->loadMultiple($file_ids)); print "Supplier portal local acceptance fixtures removed.\n";
